UPDATE COMMUNITY_POST SET VIEW_COUNT = VIEW_COUNT + 1
WHERE POST_ID = #{postId}
    AND POST_TYPE = 0 AND STATUS = 0 AND DELETED_AT IS NULL

UPDATE COMMUNITY_POST SET STATUS = 1, UPDATED_AT = SYSTIMESTAMP
WHERE POST_ID = #{postId}
    AND POST_TYPE = 0 AND STATUS = 0 AND DELETED_AT IS NULL

mapper.insert:
INSERT INTO POST_LIKE(POST_ID, MEMBER_ID, CREATED_AT)
SELECT P.POST_ID, #{memberId}, SYSTIMESTAMP
FROM COMMUNITY_POST P
WHERE P.POST_ID = #{postId}
    AND P.POST_TYPE = 0 AND P.STATUS = 0 AND P.DELETED_AT IS NULL
    AND NOT EXISTS (
        SELECT 1 FROM POST_LIKE L
        WHERE L.POST_ID = P.POST_ID AND L.MEMBER_ID = #{memberId}
    )
